mapper.select:
SELECT COUNT(*)
FROM claim
WHERE deleted = 0

    AND DATE(reported_at) >= #{startDate}


    AND DATE(reported_at) <= #{endDate}

SELECT COUNT(*)
FROM claim
WHERE deleted = 0
  AND status = 15

    AND DATE(closed_at) >= #{startDate}


    AND DATE(closed_at) <= #{endDate}

SELECT COALESCE(SUM(paid_amount), 0)
FROM claim
WHERE deleted = 0
  AND status = 14

    AND DATE(payment_completed_at) >= #{startDate}


    AND DATE(payment_completed_at) <= #{endDate}

SELECT COALESCE(AVG(DATEDIFF(closed_at, reported_at)), 0) FROM claim WHERE deleted = 0 AND status = 15 AND closed_at IS NOT NULL AND reported_at IS NOT NULL
AND DATE(reported_at) >= #{startDate}
AND DATE(reported_at) <= #{endDate}

SELECT COUNT(*)
FROM claim
WHERE deleted = 0
  AND status = 16

    AND DATE(updated_at) >= #{startDate}


    AND DATE(updated_at) <= #{endDate}

SELECT COUNT(*)
FROM claim
WHERE deleted = 0
  AND fraud_suspicious = 1

    AND DATE(reported_at) >= #{startDate}


    AND DATE(reported_at) <= #{endDate}

SELECT c.insurance_type, CASE c.insurance_type WHEN 1 THEN '车险' WHEN 2 THEN '家财险' WHEN 3 THEN '企财险' ELSE '未知' END AS insurance_type_name, COUNT(*) AS claim_count, COALESCE(SUM(c.paid_amount), 0) AS payment_amount, COALESCE(SUM(c.paid_amount) / NULLIF(SUM(p.total_premium), 0) * 100, 0) AS loss_ratio, COALESCE(SUM(c.paid_amount) / NULLIF(COUNT(*), 0), 0) AS average_payment FROM claim c LEFT JOIN policy p ON c.policy_no = p.policy_no AND p.deleted = 0 WHERE c.deleted = 0
AND DATE(c.reported_at) >= #{startDate}
AND DATE(c.reported_at) <= #{endDate}
GROUP BY c.insurance_type ORDER BY claim_count DESC

SELECT p.branch_code, p.branch_name, COUNT(*) AS claim_count, COALESCE(SUM(c.paid_amount), 0) AS payment_amount, COALESCE(SUM(c.paid_amount) / NULLIF(SUM(p.total_premium), 0) * 100, 0) AS loss_ratio, COALESCE(SUM(CASE WHEN c.status = 15 THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) * 100, 0) AS closure_rate FROM claim c LEFT JOIN policy p ON c.policy_no = p.policy_no AND p.deleted = 0 WHERE c.deleted = 0
AND DATE(c.reported_at) >= #{startDate}
AND DATE(c.reported_at) <= #{endDate}
GROUP BY p.branch_code, p.branch_name ORDER BY claim_count DESC

SELECT DATE_FORMAT(c.reported_at, '%Y-%m') AS month, COUNT(*) AS claim_count, COALESCE(SUM(c.paid_amount), 0) AS payment_amount, COALESCE(SUM(c.paid_amount) / NULLIF(SUM(p.total_premium), 0) * 100, 0) AS loss_ratio, COALESCE(SUM(CASE WHEN c.status = 15 THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) * 100, 0) AS closure_rate FROM claim c LEFT JOIN policy p ON c.policy_no = p.policy_no AND p.deleted = 0 WHERE c.deleted = 0
AND DATE(c.reported_at) >= #{startDate}
AND DATE(c.reported_at) <= #{endDate}
GROUP BY DATE_FORMAT(c.reported_at, '%Y-%m') ORDER BY month ASC
